import{_ as l,o as e,c as i,O as o}from"./chunks/framework.db831a78.js";const b=JSON.parse('{"title":"MySQL","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/05-MySQL.md","filePath":"interview/后端/Java/05-MySQL.md","lastUpdated":null}'),r={name:"interview/后端/Java/05-MySQL.md"};function t(d,a,h,n,u,c){return e(),i("div",null,a[0]||(a[0]=[o('<h1 id="mysql" tabindex="-1">MySQL <a class="header-anchor" href="#mysql" aria-label="Permalink to &quot;MySQL&quot;">​</a></h1><blockquote><p>常问等级：★★★ 高频必考 / ★★☆ 中频常见 / ★☆☆ 低频了解 深度标准：每个考点讲清「是什么 → 为什么 → 源码关键点 → 追问应对 → 易错点」。</p></blockquote><hr><h2 id="innodb-与-myisam-区别-★★★" tabindex="-1">InnoDB 与 MyISAM 区别 ★★★ <a class="header-anchor" href="#innodb-与-myisam-区别-★★★" aria-label="Permalink to &quot;InnoDB 与 MyISAM 区别 ★★★&quot;">​</a></h2><table><thead><tr><th>维度</th><th>InnoDB</th><th>MyISAM</th></tr></thead><tbody><tr><td>事务</td><td>支持（ACID）</td><td>不支持</td></tr><tr><td>锁</td><td>行级锁（+表锁/间隙锁）</td><td>表级锁</td></tr><tr><td>外键</td><td>支持</td><td>不支持</td></tr><tr><td>崩溃恢复</td><td>支持（redo/undo）</td><td>不支持（易损坏）</td></tr><tr><td>索引</td><td>聚簇索引（数据即索引）</td><td>非聚簇（索引与数据分离）</td></tr><tr><td>全文索引</td><td>MySQL5.6+ 支持</td><td>支持</td></tr><tr><td>适用</td><td>默认、OLTP 事务场景</td><td>只读/日志等无事务场景</td></tr></tbody></table><ul><li>MySQL5.5+ 默认引擎是 InnoDB，绝大多数场景选 InnoDB。</li></ul><h3 id="追问应对" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「为什么 MyISAM 查询快？」→ 无事务开销、表级锁简单、索引数据分离，但并发写和可靠性差。</li></ul><hr><h2 id="索引的数据结构-为什么是-b-树-★★★" tabindex="-1">索引的数据结构：为什么是 B+ 树 ★★★ <a class="header-anchor" href="#索引的数据结构-为什么是-b-树-★★★" aria-label="Permalink to &quot;索引的数据结构：为什么是 B+ 树 ★★★&quot;">​</a></h2><h3 id="为什么不用其他结构" tabindex="-1">为什么不用其他结构 <a class="header-anchor" href="#为什么不用其他结构" aria-label="Permalink to &quot;为什么不用其他结构&quot;">​</a></h3><ul><li>哈希：只支持等值查询、无法范围查询、无法排序，冲突退化。</li><li>二叉搜索树/AVL：树过高，磁盘 IO 次数多（树高决定 IO 次数）。</li><li>红黑树：仍是二叉，高度高。</li><li>B 树：每个节点既存索引又存数据，单个节点能存的关键字少，树更高、IO 多。</li><li>B+ 树：数据只存叶子节点、非叶子只存索引（能存更多索引，树更矮，IO 少）；叶子节点用链表连接，天然支持范围查询和排序。</li></ul><h3 id="b-树特点" tabindex="-1">B+ 树特点 <a class="header-anchor" href="#b-树特点" aria-label="Permalink to &quot;B+ 树特点&quot;">​</a></h3><ul><li>所有数据在叶子层，非叶节点仅索引，树高通常 2~4 层，3 层即可存千万级数据。</li><li>叶子节点之间用双向链表相连，支持范围扫描。</li><li>磁盘按页（默认 16KB）读取，B+ 树一个节点一页，减少 IO。</li></ul><h3 id="追问应对-1" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-1" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「B+ 树和 B 树区别？」→ B+ 树数据只在叶子、非叶只存索引、叶子有链表，范围查询更优、树更矮。</li><li>「为什么不用哈希做主键索引？」→ 哈希不支持范围、排序、最左前缀。</li></ul><hr><h2 id="聚簇索引与非聚簇索引、回表-★★★" tabindex="-1">聚簇索引与非聚簇索引、回表 ★★★ <a class="header-anchor" href="#聚簇索引与非聚簇索引、回表-★★★" aria-label="Permalink to &quot;聚簇索引与非聚簇索引、回表 ★★★&quot;">​</a></h2><h3 id="聚簇索引-主键索引" tabindex="-1">聚簇索引（主键索引） <a class="header-anchor" href="#聚簇索引-主键索引" aria-label="Permalink to &quot;聚簇索引（主键索引）&quot;">​</a></h3><ul><li>数据和索引存在一起，叶子节点存的是整行数据。</li><li>每张表只能有一个聚簇索引（因为数据只能存一份），通常是主键。</li></ul><h3 id="非聚簇索引-二级索引-辅助索引" tabindex="-1">非聚簇索引（二级索引/辅助索引） <a class="header-anchor" href="#非聚簇索引-二级索引-辅助索引" aria-label="Permalink to &quot;非聚簇索引（二级索引/辅助索引）&quot;">​</a></h3><ul><li>叶子节点存的是「索引列 + 主键值」。</li><li>通过二级索引查到主键，再回「聚簇索引」查整行数据，这个过程叫「回表」。</li></ul><h3 id="覆盖索引" tabindex="-1">覆盖索引 <a class="header-anchor" href="#覆盖索引" aria-label="Permalink to &quot;覆盖索引&quot;">​</a></h3><ul><li>查询的列都在二级索引里，不用回表，性能最好（<code>SELECT 索引列 FROM ...</code>）。</li><li>经典优化：把要查的列建成联合索引，实现覆盖索引避免回表。</li></ul><h3 id="追问应对-2" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-2" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「为什么主键建议自增？」→ 自增主键顺序插入，页分裂少；UUID 随机插入会导致频繁页分裂、索引碎片。</li><li>「回表一定慢吗？」→ 回表多一次 IO；用覆盖索引可避免。</li></ul><hr><h2 id="最左前缀原则、联合索引-★★★" tabindex="-1">最左前缀原则、联合索引 ★★★ <a class="header-anchor" href="#最左前缀原则、联合索引-★★★" aria-label="Permalink to &quot;最左前缀原则、联合索引 ★★★&quot;">​</a></h2><h3 id="原则" tabindex="-1">原则 <a class="header-anchor" href="#原则" aria-label="Permalink to &quot;原则&quot;">​</a></h3><ul><li>联合索引 (a, b, c) 遵循最左前缀：只有从最左列开始连续匹配才能命中索引。</li><li>可命中：<code>a</code>、<code>a,b</code>、<code>a,b,c</code>、<code>a,c</code>（a 能命中，但 c 无法用索引，因为中间 b 断了）。</li><li>不可命中：<code>b</code>、<code>c</code>、<code>b,c</code>（未从 a 开始）。</li></ul><h3 id="为什么" tabindex="-1">为什么 <a class="header-anchor" href="#为什么" aria-label="Permalink to &quot;为什么&quot;">​</a></h3><ul><li>联合索引按 (a,b,c) 的字典序排列，跳过 a 直接用 b 无法利用有序性。</li></ul><h3 id="设计原则" tabindex="-1">设计原则 <a class="header-anchor" href="#设计原则" aria-label="Permalink to &quot;设计原则&quot;">​</a></h3><ul><li>区分度高的列放最左、经常用于 where/order by/group by 的列优先。</li></ul><h3 id="追问应对-3" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-3" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「范围查询会中断索引吗？」→ 会，<code>a = 1 AND b &gt; 2</code> 只能用到 a 和 b，b 之后（c）失效；所以范围列尽量放联合索引靠后位置。</li></ul><hr><h2 id="索引失效场景-★★★" tabindex="-1">索引失效场景 ★★★ <a class="header-anchor" href="#索引失效场景-★★★" aria-label="Permalink to &quot;索引失效场景 ★★★&quot;">​</a></h2><ul><li>对索引列做函数/运算（<code>WHERE YEAR(create_time)=2024</code>、<code>WHERE id+1=5</code>）。</li><li>隐式类型转换（<code>WHERE phone = 138...</code>，phone 是字符串却没加引号）。</li><li>最左前缀不满足（跳过最左列）。</li><li>范围查询之后的列失效。</li><li>用 <code>!=</code>、<code>&lt;&gt;</code>、<code>NOT IN</code>、<code>NOT EXISTS</code>（部分情况）。</li><li><code>LIKE &#39;%xx&#39;</code> 前导模糊（<code>LIKE &#39;xx%&#39;</code> 可走索引，<code>&#39;%xx&#39;</code> 不能）。</li><li>OR 连接的非索引列。</li><li>优化器认为全表扫描更快（数据量小时可能不走索引）。</li></ul><h3 id="追问应对-4" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-4" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「怎么判断走了索引？」→ <code>EXPLAIN</code> 看 type（const/ref/range 好，ALL 全表扫）、key、rows。</li></ul><hr><h2 id="explain-关键字段-★★★" tabindex="-1">EXPLAIN 关键字段 ★★★ <a class="header-anchor" href="#explain-关键字段-★★★" aria-label="Permalink to &quot;EXPLAIN 关键字段 ★★★&quot;">​</a></h2><ul><li>type（访问类型，从好到差）：system &gt; const &gt; eq_ref &gt; ref &gt; range &gt; index &gt; ALL。</li><li>key：实际使用的索引；possible_keys：可能用到的索引。</li><li>rows：预估扫描行数。</li><li>Extra： <ul><li>Using index：覆盖索引（好，不用回表）。</li><li>Using where：存储引擎层过滤后还需回表过滤。</li><li>Using filesort：额外排序（可优化，加索引避免）。</li><li>Using temporary：用了临时表（group by/distinct 未用索引，需优化）。</li></ul></li></ul><h3 id="追问应对-5" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-5" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「type 为 ALL 怎么办？」→ 检查是否缺索引/索引失效，加合适索引。</li></ul><hr><h2 id="事务-acid-及实现原理-★★★" tabindex="-1">事务 ACID 及实现原理 ★★★ <a class="header-anchor" href="#事务-acid-及实现原理-★★★" aria-label="Permalink to &quot;事务 ACID 及实现原理 ★★★&quot;">​</a></h2><ul><li>原子性（Atomicity）：要么全成功要么全失败 → undo log 回滚实现。</li><li>一致性（Consistency）：事务前后数据满足约束 → 由其他三个特性共同保证。</li><li>隔离性（Isolation）：并发事务互不干扰 → 锁 + MVCC。</li><li>持久性（Durability）：提交后不丢失 → redo log 落盘。</li></ul><h3 id="追问应对-6" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-6" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「redo 和 undo 区别？」→ redo 记录「改了什么」用于崩溃恢复（持久性）；undo 记录「改之前的值」用于回滚和 MVCC（原子性/隔离性）。</li></ul><hr><h2 id="事务隔离级别与并发问题-★★★" tabindex="-1">事务隔离级别与并发问题 ★★★ <a class="header-anchor" href="#事务隔离级别与并发问题-★★★" aria-label="Permalink to &quot;事务隔离级别与并发问题 ★★★&quot;">​</a></h2><h3 id="三种并发问题" tabindex="-1">三种并发问题 <a class="header-anchor" href="#三种并发问题" aria-label="Permalink to &quot;三种并发问题&quot;">​</a></h3><ul><li>脏读：读到别的事务未提交的数据。</li><li>不可重复读：同一事务两次读，中间别的事务提交了 update，两次结果不一致。</li><li>幻读：同一事务两次读，中间别的事务 insert/delete，导致行数变化。</li></ul><h3 id="四种隔离级别" tabindex="-1">四种隔离级别 <a class="header-anchor" href="#四种隔离级别" aria-label="Permalink to &quot;四种隔离级别&quot;">​</a></h3><ul><li>读未提交（Read Uncommitted）：三种问题都可能。</li><li>读已提交（Read Committed，RC）：解决脏读。</li><li>可重复读（Repeatable Read，RR，MySQL 默认）：解决脏读、不可重复读，MVCC 下基本解决幻读。</li><li>串行化（Serializable）：全部解决，但并发差。</li></ul><h3 id="追问应对-7" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-7" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「MySQL 默认 RR 为什么？」→ RR 通过 MVCC + 间隙锁（Next-Key Lock）基本解决幻读，且并发比串行化好。</li><li>「Oracle 默认是什么？」→ RC，所以面试常考 MySQL 与 Oracle 默认隔离级别差异。</li></ul><hr><h2 id="mvcc-多版本并发控制-★★★" tabindex="-1">MVCC 多版本并发控制 ★★★ <a class="header-anchor" href="#mvcc-多版本并发控制-★★★" aria-label="Permalink to &quot;MVCC 多版本并发控制 ★★★&quot;">​</a></h2><h3 id="原理" tabindex="-1">原理 <a class="header-anchor" href="#原理" aria-label="Permalink to &quot;原理&quot;">​</a></h3><ul><li>通过「隐藏列 + undo log + ReadView」实现无锁读写并发。</li><li>每行有隐藏列：<code>DB_TRX_ID</code>（最近修改事务 id）、<code>DB_ROLL_PTR</code>（回滚指针指向 undo log 旧版本）、<code>DB_ROW_ID</code>（无主键时生成）。</li><li>读操作根据 ReadView（快照）判断哪些版本可见，读的是历史版本，不与写互斥。</li></ul><h3 id="readview-可见性规则" tabindex="-1">ReadView 可见性规则 <a class="header-anchor" href="#readview-可见性规则" aria-label="Permalink to &quot;ReadView 可见性规则&quot;">​</a></h3><ul><li>记录版本事务 id &lt; 当前活跃最小事务 id → 可见；&gt; 当前事务 id → 不可见（沿 undo 链往前找）。</li></ul><h3 id="rc-与-rr-的-readview-区别" tabindex="-1">RC 与 RR 的 ReadView 区别 <a class="header-anchor" href="#rc-与-rr-的-readview-区别" aria-label="Permalink to &quot;RC 与 RR 的 ReadView 区别&quot;">​</a></h3><ul><li>RC：每次 SELECT 生成新 ReadView（能看到别的事务已提交的修改）。</li><li>RR：事务内第一次 SELECT 生成 ReadView，之后复用（保证可重复读）。</li></ul><h3 id="追问应对-8" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-8" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「MVCC 解决了什么？」→ 读写不阻塞，解决脏读/不可重复读/幻读（RR 下）。</li></ul><hr><h2 id="mysql-锁-行锁、表锁、间隙锁、临键锁-★★★" tabindex="-1">MySQL 锁：行锁、表锁、间隙锁、临键锁 ★★★ <a class="header-anchor" href="#mysql-锁-行锁、表锁、间隙锁、临键锁-★★★" aria-label="Permalink to &quot;MySQL 锁：行锁、表锁、间隙锁、临键锁 ★★★&quot;">​</a></h2><ul><li>全局锁/表锁/行锁，行锁是 InnoDB 的。</li><li>行锁：记录锁（Record Lock）锁单行；间隙锁（Gap Lock）锁区间防插入；临键锁（Next-Key Lock）= 记录锁 + 间隙锁，锁定「左开右闭」区间。</li><li>行锁在 RR 隔离级别下用来解决幻读。</li></ul><h3 id="死锁与排查" tabindex="-1">死锁与排查 <a class="header-anchor" href="#死锁与排查" aria-label="Permalink to &quot;死锁与排查&quot;">​</a></h3><ul><li>死锁产生：两个事务互相等待对方的锁。</li><li>排查：<code>SHOW ENGINE INNODB STATUS</code> 看 <code>LATEST DETECTED DEADLOCK</code>；<code>SELECT * FROM information_schema.innodb_trx</code> 看当前事务。</li></ul><h3 id="追问应对-9" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-9" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「为什么 RR 要用间隙锁？」→ 防止其他事务在范围内插入，解决幻读；代价是降低并发。</li></ul><hr><h2 id="三大范式与反范式-★★☆" tabindex="-1">三大范式与反范式 ★★☆ <a class="header-anchor" href="#三大范式与反范式-★★☆" aria-label="Permalink to &quot;三大范式与反范式 ★★☆&quot;">​</a></h2><ul><li>1NF：列不可再分（原子性）。</li><li>2NF：非主键列完全依赖主键（消除部分依赖，针对联合主键）。</li><li>3NF：非主键列不传递依赖主键（消除传递依赖）。</li><li>反范式：为性能冗余字段（如订单表冗余用户名），用空间换时间，减少 join。</li></ul><h3 id="追问应对-10" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-10" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「什么时候反范式？」→ 高频查询需要冗余、join 成本高时；权衡一致性与性能。</li></ul><hr><h2 id="三大日志-redo-log、undo-log、binlog-★★★" tabindex="-1">三大日志：redo log、undo log、binlog ★★★ <a class="header-anchor" href="#三大日志-redo-log、undo-log、binlog-★★★" aria-label="Permalink to &quot;三大日志：redo log、undo log、binlog ★★★&quot;">​</a></h2><h3 id="redo-log-重做日志-innodb" tabindex="-1">redo log（重做日志，InnoDB） <a class="header-anchor" href="#redo-log-重做日志-innodb" aria-label="Permalink to &quot;redo log（重做日志，InnoDB）&quot;">​</a></h3><ul><li>记录「数据页做了什么修改」，用于崩溃恢复（持久性）。</li><li>特点：顺序写、循环写（固定大小，写满触发刷盘）、WAL（先写日志再写磁盘）。</li><li><code>innodb_flush_log_at_trx_commit=1</code> 每次提交刷盘（最安全）。</li></ul><h3 id="undo-log-回滚日志" tabindex="-1">undo log（回滚日志） <a class="header-anchor" href="#undo-log-回滚日志" aria-label="Permalink to &quot;undo log（回滚日志）&quot;">​</a></h3><ul><li>记录「修改前的值」，用于回滚和 MVCC。</li></ul><h3 id="binlog-二进制日志-server-层" tabindex="-1">binlog（二进制日志，Server 层） <a class="header-anchor" href="#binlog-二进制日志-server-层" aria-label="Permalink to &quot;binlog（二进制日志，Server 层）&quot;">​</a></h3><ul><li>记录所有逻辑变更（SQL），用于主从复制、数据恢复。</li><li>三种格式：statement（SQL 语句）、row（行变更，主流）、mixed。</li></ul><h3 id="redo-和-binlog-区别" tabindex="-1">redo 和 binlog 区别 <a class="header-anchor" href="#redo-和-binlog-区别" aria-label="Permalink to &quot;redo 和 binlog 区别&quot;">​</a></h3><ul><li>redo 是 InnoDB 引擎层、物理日志、循环写；binlog 是 Server 层、逻辑日志、追加写。</li><li>两阶段提交保证 redo 与 binlog 一致。</li></ul><h3 id="追问应对-11" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-11" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「为什么需要两阶段提交？」→ 保证 redo 与 binlog 一致，避免主从复制数据不一致。</li></ul><hr><h2 id="主从复制原理-★★★" tabindex="-1">主从复制原理 ★★★ <a class="header-anchor" href="#主从复制原理-★★★" aria-label="Permalink to &quot;主从复制原理 ★★★&quot;">​</a></h2><ul><li>流程：主库写 binlog → 从库 IO 线程读 binlog 写 relay log → 从库 SQL 线程执行 relay log。</li><li>作用：读写分离、数据备份、高可用。</li><li>延迟原因：从库 SQL 单线程重放慢、大事务、主从配置差、网络。</li></ul><h3 id="追问应对-12" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-12" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「主从延迟怎么解决？」→ 并行复制（多线程 SQL）、优化大事务、升级硬件、读写分离时对实时性要求高的读走主库。</li></ul><hr><h2 id="慢查询优化思路-★★★" tabindex="-1">慢查询优化思路 ★★★ <a class="header-anchor" href="#慢查询优化思路-★★★" aria-label="Permalink to &quot;慢查询优化思路 ★★★&quot;">​</a></h2><ol><li>定位：慢查询日志（<code>slow_query_log</code>）、<code>EXPLAIN</code> 分析。</li><li>看 type 是否为 ALL（全表扫）、是否缺索引。</li><li>加合适索引（遵循最左前缀、覆盖索引、避免失效）。</li><li>优化 SQL（避免 <code>SELECT *</code>、避免函数作用于索引列、小表驱动大表）。</li><li>分库分表/读写分离/缓存（Redis）。</li></ol><h3 id="追问应对-13" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-13" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「一条 SQL 突然变慢怎么排查？」→ 看是否缺索引/索引失效/数据量增长/锁等待/大事务；用 EXPLAIN 和慢日志定位。</li></ul><hr><h2 id="分库分表-★★☆" tabindex="-1">分库分表 ★★☆ <a class="header-anchor" href="#分库分表-★★☆" aria-label="Permalink to &quot;分库分表 ★★☆&quot;">​</a></h2><ul><li>垂直拆分：按业务拆库（订单库、用户库）；按列拆表（热冷字段）。</li><li>水平拆分：按行拆（按 id 哈希/范围分片到多表多库）。</li><li>中间件：ShardingSphere、MyCat。</li><li>问题：分布式主键（雪花算法）、跨库 join、分布式事务、路由。</li></ul><h3 id="追问应对-14" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-14" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「什么时候需要分库分表？」→ 单表千万级、单库连接数/容量瓶颈时；优先索引优化、缓存、读写分离，最后才分库分表。</li></ul><hr><h2 id="大表如何优化-★★★" tabindex="-1">大表如何优化 ★★★ <a class="header-anchor" href="#大表如何优化-★★★" aria-label="Permalink to &quot;大表如何优化 ★★★&quot;">​</a></h2><ul><li>索引优化、覆盖索引、避免回表。</li><li>冷热数据分离、归档历史数据。</li><li>读写分离、缓存热点数据。</li><li>垂直拆分 + 水平分库分表。</li><li>换列式存储/大数据引擎（可选）。</li></ul><hr><h2 id="mysql-优化器、执行顺序-★★☆" tabindex="-1">MySQL 优化器、执行顺序 ★★☆ <a class="header-anchor" href="#mysql-优化器、执行顺序-★★☆" aria-label="Permalink to &quot;MySQL 优化器、执行顺序 ★★☆&quot;">​</a></h2><ul><li>SQL 执行顺序：FROM → JOIN/ON → WHERE → GROUP BY → HAVING → SELECT → DISTINCT → ORDER BY → LIMIT。</li><li>理解执行顺序有助于写正确 SQL（如 WHERE 在 GROUP BY 前，聚合条件用 HAVING）。</li></ul><h3 id="易错点" tabindex="-1">易错点 <a class="header-anchor" href="#易错点" aria-label="Permalink to &quot;易错点&quot;">​</a></h3><ul><li>WHERE 不能用聚合函数，HAVING 可以；别名在 SELECT 之后才生效，WHERE 里不能用 SELECT 的别名。</li></ul>',116)]))}const q=l(r,[["render",t]]);export{b as __pageData,q as default};
